  const apiUsages = root.find(j.MemberExpression, {
    object: { object: { name: 'api' }, type: 'MemberExpression' },
  });

  // Extract <name> and <pure|impure|models> from api.<name>.<pure|impure|models>
  const apiNames = new Map();
  apiUsages.nodes().forEach((node) => {
    const { name } = node.object.property;
    const type = node.property.name;
    if (!apiNames.has(name)) {
      apiNames.set(name, []);
    }
    if (!apiNames.get(name).includes(type)) {
      apiNames.get(name).push(type);
    }
  });

  // Change import statement and api usages for each <name> and <pure|impure|models>
  apiNames.forEach((typeList, name) => {
    const newName = `apiRest${name[0].toUpperCase() + name.slice(1).toLowerCase()}`;

    typeList.forEach((type) => {
      const finalNewName = `${newName}${type === 'models' ? 'Models' : ''}`;

      root
        .find(j.ImportDeclaration, {
          source: { value: 'utility' },
        })
        .find(j.ImportSpecifier)
        .forEach((specifier) => {
          if (specifier.node.imported.name === 'api') {
            specifier.node.imported.name = finalNewName;
            specifier.node.local.name = finalNewName;
          }
        });

      root
        .find(j.ImportDeclaration, {
          source: { value: 'utility' },
        })
        .forEach((path) => {
          const specifiers = path.node.specifiers.filter(
            (specifier) => specifier.imported.name !== 'api'
          );
          if (specifiers.length > 0) {
            path.replace(j.importDeclaration(specifiers, j.literal('utility')));
          } else {
            path.prune();
          }
        });

      root
        .find(j.ImportDeclaration, {
          source: { value: 'utility' },
        })
        .insertAfter(
          j.importDeclaration(
            [j.importSpecifier(j.identifier(finalNewName))],
            j.literal(`api-rest-${name.toLowerCase()}`)
          )
        );
    });
  });

  // Change api usages for each <name> and <pure|impure|models>
  apiUsages.forEach((memberExpression) => {
    const { name } = memberExpression.node.object.property;
    const type = memberExpression.node.property.name;
    const newName = `apiRest${name[0].toUpperCase() + name.slice(1).toLowerCase()}`;
    const finalNewName = `${newName}${type === 'models' ? 'Models' : ''}`;

    memberExpression.node.object = j.identifier(finalNewName);
