function cycleCutset(problem)
  // Initialize the set of feasible solutions to the problem
  feasibleSolutions = { }

  // Divide the problem into cycles and cuts
  cycles = cycle(problem)
  cuts = cut(problem)

  // Initialize the current solution
  currentSolution = { }

  // Loop over the cycles and cuts
  for each cycle in cycles
    for each cut in cuts
      // If the current cycle and cut is infeasible, backtrack
      if infeasible(cycle, cut, problem)
        continue

      // If the current cycle and cut is a solution, add it to the set of feasible solutions
      if solution(cycle, cut, problem)
        feasibleSolutions.add(currentSolution)
        break

      // Generate the child solutions by removing the current cut
      childSolutions = generateChildren(cycle, cut, problem)

      // Add each child solution to the set of feasible solutions
      for each childSolution in childSolutions
        feasibleSolutions.add(childSolution)

      // Update the current solution to the child solution
      currentSolution = childSolution

  return feasibleSolutions
