SYSCALL_DEFINE2(cp_range, void *, start_addr, void *, end_addr) {
    struct file *file;
    mm_segment_t old_fs;
    char *filename;
    loff_t pos = 0;
    int ret;
    unsigned long len;
    unsigned int rnd;

    // Generate a unique filename using the current time and a random number
    get_random_bytes(&rnd, sizeof(rnd));
    filename = kmalloc(128, GFP_KERNEL);
    if (!filename) {
        return -ENOMEM;
    }
    snprintf(filename, 128, "/tmp/cp_range_output_%lu_%u", (unsigned long)current_kernel_time().tv_sec, rnd);

    old_fs = get_fs();
    set_fs(KERNEL_DS);

    file = filp_open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (IS_ERR(file)) {
        ret = PTR_ERR(file);
        goto out_set_fs;
    }

    len = (unsigned long)end_addr - (unsigned long)start_addr + 1;
    ret = vfs_write(file, (char *)start_addr, len, &pos);

    filp_close(file, NULL);

out_set_fs:
    set_fs(old_fs);
    kfree(filename);
    return ret;
}
```
